/**
 * GDD §10 — the Diplomacy Archive.
 *
 * Every signed treaty a guild is party to, readable by EVERY member of that
 * guild (no diplomacy rank required), searchable, and openable as the full
 * frozen instrument.
 *
 * The framing is the whole point: a signed document restricts nothing. It is
 * a timestamped, counter-signed record, which is what makes betrayal provable
 * rather than impossible.
 */
import type { IBackend } from '../../backend/IBackend';
import { archiveFor } from '../../game/diplomacy/diplomacy';
import type { GameState, Treaty } from '../../game/types';
import { badge, emptyState, openModal, panel, sectionHeader } from '../components';
import { clear, cssHex, el } from '../dom';
import { guildSigil } from '../components';

/** `2026.07.28 · 14:32` — console-log stamp, stable across locales. */
export function stamp(at: number): string {
  const d = new Date(at);
  const p = (n: number): string => String(n).padStart(2, '0');
  return `${d.getFullYear()}.${p(d.getMonth() + 1)}.${p(d.getDate())} · ${p(d.getHours())}:${p(
    d.getMinutes(),
  )}`;
}

export interface TreatyDocumentOpts {
  /** Render an unexecuted draft with a status stripe instead of signatures. */
  draft?: boolean;
}

/**
 * The signed instrument, rendered as a diplomatic document on holographic film:
 * both guild crests, the seal, the frozen text, both signatures with names and
 * timestamps, and the standing notice that it binds nothing but reputation.
 */
export function treatyDocument(
  state: GameState,
  treaty: Treaty,
  opts: TreatyDocumentOpts = {},
): HTMLElement {
  const [aId, bId] = treaty.guilds;
  const a = state.guilds[aId];
  const b = state.guilds[bId];

  const doc = el('article', { class: 'doc' });
  doc.appendChild(el('span', { class: 'doc__edge doc__edge--t', aria: { hidden: 'true' } }));

  const crest = el('div', { class: 'doc__crest' });
  if (a) crest.appendChild(guildSigil(a, 34));
  crest.appendChild(
    el(
      'div',
      { class: 'doc__seal' },
      el('span', { text: treaty.status === 'signed' ? 'SEALED' : 'DRAFT' }),
    ),
  );
  if (b) crest.appendChild(guildSigil(b, 34));
  doc.appendChild(crest);

  doc.appendChild(el('h2', { class: 'doc__title', text: treaty.title }));
  doc.appendChild(
    el('div', {
      class: 'doc__sub',
      text:
        treaty.status === 'signed' && treaty.signedAt !== undefined
          ? `INSTRUMENT ${treaty.id.toUpperCase()} · EXECUTED ${stamp(treaty.signedAt)}`
          : `INSTRUMENT ${treaty.id.toUpperCase()} · OPENED ${stamp(treaty.createdAt)}`,
    }),
  );
  doc.appendChild(
    el('div', {
      class: 'doc__sub',
      text: `BETWEEN ${a ? `${a.name} [${a.tag}]` : 'UNKNOWN'} AND ${
        b ? `${b.name} [${b.tag}]` : 'UNKNOWN'
      }`,
    }),
  );

  doc.appendChild(el('div', { class: 'doc__rule', aria: { hidden: 'true' } }));
  doc.appendChild(
    el('div', {
      class: 'doc__body selectable',
      text: treaty.text.trim().length > 0 ? treaty.text : '— the page is blank —',
    }),
  );

  const sigs = el('div', { class: 'doc__sigs' });
  for (const guildId of treaty.guilds) {
    const guild = state.guilds[guildId];
    const signature = treaty.signatures.find((s) => s.guildId === guildId);
    const cell = el('div', { class: 'sig' });
    if (signature) {
      cell.appendChild(el('div', { class: 'sig__scrawl', text: signature.playerName }));
      cell.appendChild(
        el('div', {
          class: 'sig__who',
          style: guild ? `color:${cssHex(guild.color)}` : undefined,
          text: guild ? `${guild.name} [${guild.tag}]` : guildId,
        }),
      );
      cell.appendChild(el('div', { class: 'sig__at', text: stamp(signature.at) }));
    } else {
      cell.appendChild(el('div', { class: 'sig__scrawl dim-2', text: '— unsigned —' }));
      cell.appendChild(
        el('div', { class: 'sig__who', text: guild ? `${guild.name} [${guild.tag}]` : guildId }),
      );
      cell.appendChild(el('div', { class: 'sig__at', text: 'awaiting signature' }));
    }
    sigs.appendChild(cell);
  }
  doc.appendChild(sigs);

  doc.appendChild(
    el('div', {
      class: 'doc__foot',
      text:
        opts.draft && treaty.status !== 'signed'
          ? 'Unexecuted draft. Nothing here is in force, and nothing here would restrict a game action even once it is.'
          : 'This instrument is socially enforced only. It restricts no movement, no capture, no battle and no trade. It exists so that keeping your word — or breaking it — is a matter of record.',
    }),
  );
  doc.appendChild(el('span', { class: 'doc__edge doc__edge--b', aria: { hidden: 'true' } }));
  return doc;
}

/** Opens a signed instrument full-screen in a modal. */
export function openTreatyDocument(state: GameState, treaty: Treaty): void {
  openModal({
    title: treaty.status === 'signed' ? 'EXECUTED INSTRUMENT' : 'DRAFT INSTRUMENT',
    body: treatyDocument(state, treaty, { draft: treaty.status !== 'signed' }),
    accent: 'var(--gold)',
    class: 'modal-layer--doc',
    actions: [{ label: 'CLOSE', variant: 'ghost' }],
  });
}

// ─────────────────────────────────────────────────────────────────────────────
// Archive list
// ─────────────────────────────────────────────────────────────────────────────

export interface ArchiveView {
  readonly el: HTMLElement;
  sync(state: GameState): void;
  dispose(): void;
}

function matches(treaty: Treaty, state: GameState, needle: string): boolean {
  if (needle.length === 0) return true;
  const haystack = [
    treaty.title,
    treaty.text,
    ...treaty.signatures.map((s) => s.playerName),
    ...treaty.guilds.map((g) => `${state.guilds[g]?.name ?? ''} ${state.guilds[g]?.tag ?? ''}`),
  ]
    .join(' ')
    .toLowerCase();
  return haystack.includes(needle);
}

export function createArchiveView(backend: IBackend): ArchiveView {
  void backend; // the archive is a pure read of published state

  const search = el('input', {
    class: 'field__input',
    attrs: { type: 'search', placeholder: 'SEARCH TITLES, TERMS, SIGNATORIES…', autocomplete: 'off' },
  });
  const list = el('div', { class: 'col' });
  let needle = '';
  let signature = '';

  search.addEventListener('input', () => {
    needle = search.value.trim().toLowerCase();
    signature = '';
    const state = lastState;
    if (state) render(state);
  });

  const proof = el(
    'div',
    { class: 'arch__proof' },
    el('b', { text: 'BETRAYAL IS PROVABLE. ' }),
    'Signed instruments never restrict a single game action — no wall goes up, no order is blocked. What they do is fix the terms, the names and the hour in a record both guilds can read forever. Honour it or do not; the archive does not forget either way.',
  );

  const root = el(
    'div',
    { class: 'gpane' },
    el(
      'div',
      { class: 'gscroll' },
      panel(
        { title: 'DIPLOMACY ARCHIVE', subtitle: 'readable by every member of the guild', accent: 'var(--gold)' },
        proof,
        el(
          'div',
          { class: 'field selectable' },
          el('span', { class: 'field__label', text: 'SEARCH' }),
          search,
        ),
        sectionHeader('EXECUTED INSTRUMENTS'),
        list,
      ),
    ),
  );

  let lastState: GameState | null = null;

  function render(state: GameState): void {
    const me = state.players[state.meId];
    const guildId = me?.guildId;
    if (!guildId) {
      clear(list);
      list.appendChild(emptyState('◇', 'no guild, no archive'));
      signature = 'none';
      return;
    }

    const treaties = archiveFor(state, guildId).filter((t) => matches(t, state, needle));
    const next = `${guildId}:${needle}:${treaties.map((t) => t.id).join(',')}`;
    if (next === signature) return;
    signature = next;

    clear(list);
    if (treaties.length === 0) {
      list.appendChild(
        emptyState('◇', needle.length > 0 ? 'nothing matches that search' : 'no treaties executed yet'),
      );
      return;
    }

    for (const treaty of treaties) {
      const other = treaty.guilds.find((g) => g !== guildId);
      const otherGuild = other ? state.guilds[other] : undefined;
      const row = el('button', { class: 'arch__item', attrs: { type: 'button' } });
      if (otherGuild) {
        const sig = el('div', { class: 'dir__sig' });
        sig.appendChild(guildSigil(otherGuild, 28));
        row.appendChild(sig);
      }
      row.appendChild(
        el(
          'div',
          { class: 'grow' },
          el('div', { class: 'arch__title', text: treaty.title }),
          el('div', {
            class: 'arch__meta',
            text: `${otherGuild ? `[${otherGuild.tag}] · ` : ''}${
              treaty.signedAt !== undefined ? stamp(treaty.signedAt) : '—'
            } · ${treaty.revisions.length} REVISION${treaty.revisions.length === 1 ? '' : 'S'}`,
          }),
        ),
      );
      row.appendChild(badge('SEALED', 'gold'));
      row.addEventListener('click', () => {
        const live = lastState;
        if (live) openTreatyDocument(live, treaty);
      });
      list.appendChild(row);
    }
  }

  return {
    el: root,
    sync(state: GameState): void {
      lastState = state;
      render(state);
    },
    dispose(): void {
      lastState = null;
      signature = '';
      clear(list);
    },
  };
}
