/**
 * GDD §10 — the parley: a private cross-guild thread between the two guilds'
 * diplomats.
 *
 * Three faces of the same channel:
 *   THREAD    — the conversation itself
 *   TRADE     — structured offers (see tradePanel)
 *   DOCUMENTS — free-text treaties, opened here and drafted in the editor
 *
 * Plus the peace flag: a single shared boolean on the Parley, so either
 * diplomat can raise or lower it and both guilds are told. It is a declaration,
 * not a rule — the UI says so out loud because nothing in the game consults it.
 */
import type { IBackend } from '../../backend/IBackend';
import { otherGuild, treatiesFor } from '../../game/diplomacy/diplomacy';
import { messages, parleyChannel } from '../../game/guild/social';
import { view } from '../../game/store';
import type { GameState, ParleyId } from '../../game/types';
import {
  badge,
  button,
  ChatView,
  emptyState,
  guildSigil,
  holdButton,
  ICONS,
  panel,
  promptModal,
  sectionHeader,
  tabs,
  TAB_ICONS,
  toast,
  type TabsController,
} from '../components';
import { clear, cssHex, el, fmtAgo } from '../dom';
import { runAction } from '../guild/rosterTab';
import { stamp } from './archiveView';
import { createTradePanel } from './tradePanel';

type ParleyTab = 'thread' | 'trade' | 'docs';

export interface ParleyViewApi {
  readonly el: HTMLElement;
  sync(state: GameState): void;
  dispose(): void;
}

export function createParleyView(backend: IBackend): ParleyViewApi {
  const root = el('div', { class: 'gpane' });

  // ── header ────────────────────────────────────────────────────────────────
  const backBtn = button('BACK', {
    variant: 'quiet',
    small: true,
    icon: ICONS.chevronLeft,
    onClick: () => view.patch({ openParleyId: undefined, openTreatyId: undefined }),
  });
  const crest = el('div', { class: 'parley__vs' });
  const statusSlot = el('div', { class: 'row', style: 'gap:4px;flex:none' });
  const head = el('div', { class: 'parley__head' }, backBtn, crest, statusSlot);

  // ── peace flag ────────────────────────────────────────────────────────────
  const peaceKey = el('div', { class: 'peaceflag__k', text: '—' });
  const peaceSince = el('div', { class: 'peaceflag__v', text: '' });
  const peaceAction = el('div', { class: 'peaceflag__act' });
  const peaceFlag = el(
    'div',
    { class: 'peaceflag' },
    el('div', { class: 'peaceflag__state' }, peaceKey, peaceSince),
    peaceAction,
  );

  const peaceNote = el('div', {
    class: 'mono dim-2',
    style: 'font-size:9px;line-height:1.6;letter-spacing:.04em;text-transform:uppercase',
    text: 'The peace flag is informational. No movement, capture or battle checks it. It is a public statement of intent and nothing else.',
  });

  // ── panes ─────────────────────────────────────────────────────────────────
  let parleyId: ParleyId | undefined;
  let channel = '';
  let chatKey = '';

  const chatView = new ChatView({
    placeholder: 'TRANSMIT TO THE OTHER TABLE…',
    onSend: (text: string) => {
      if (!channel) return;
      void (async () => {
        const res = await backend.sendChat(channel, text);
        if (!res.ok) toast({ title: 'NOT SENT', body: res.error, kind: 'bad' });
      })();
    },
  });

  const threadPane = el(
    'div',
    { class: 'gpane' },
    el('div', { class: 'chat-host' }, chatView.el),
  );

  const tradePanelView = createTradePanel(backend);
  const tradePane = el('div', { class: 'gpane' }, el('div', { class: 'gscroll' }, tradePanelView.el));

  const docList = el('div', { class: 'col' });
  const newDocBtn = button('OPEN A BLANK DOCUMENT', {
    variant: 'primary',
    wide: true,
    icon: ICONS.plus,
    sub: 'both sides write, both sides sign',
    onClick: () => {
      const id = parleyId;
      if (!id) return;
      void (async () => {
        const title = await promptModal({
          title: 'NEW INSTRUMENT',
          label: 'Working title',
          placeholder: 'NON-AGGRESSION, KHARON CORRIDOR',
          maxLength: 60,
        });
        if (title === null) return;
        const treatyId = await runAction('DOCUMENT OPENED', backend.createTreaty(id, title));
        if (treatyId !== undefined) view.patch({ openTreatyId: treatyId });
      })();
    },
  });

  const docsPane = el(
    'div',
    { class: 'gpane' },
    el(
      'div',
      { class: 'gscroll' },
      panel(
        { title: 'DOCUMENTS', subtitle: 'socially enforced, never mechanically', accent: 'var(--gold)' },
        el('div', {
          class: 'tty__note',
          text: 'A treaty is a written record between two guilds. It freezes when both sides sign, lands in both archives, and restricts absolutely nothing on the map.',
        }),
        newDocBtn,
        sectionHeader('ON THIS CHANNEL'),
        docList,
      ),
    ),
  );

  const panes: Record<ParleyTab, HTMLElement> = {
    thread: threadPane,
    trade: tradePane,
    docs: docsPane,
  };

  let activeTab: ParleyTab = 'thread';
  const body = el('div', { class: 'gbody' }, threadPane, tradePane, docsPane);

  const subTabs: TabsController = tabs(
    [
      { id: 'thread', label: 'THREAD', icon: TAB_ICONS.chat },
      { id: 'trade', label: 'TRADE', icon: TAB_ICONS.transfers },
      { id: 'docs', label: 'DOCUMENTS', icon: TAB_ICONS.archive },
    ],
    (id: string) => {
      if (id !== 'thread' && id !== 'trade' && id !== 'docs') return;
      activeTab = id;
      applyTab();
    },
    'thread',
  );

  function applyTab(): void {
    for (const key of Object.keys(panes) as ParleyTab[]) {
      panes[key].classList.toggle('is-on', key === activeTab);
    }
  }
  applyTab();

  const preamble = el('div', { class: 'col', style: 'flex:none;gap:var(--sp-2)' }, peaceFlag, peaceNote);

  root.appendChild(head);
  root.appendChild(preamble);
  root.appendChild(el('div', { style: 'flex:none' }, subTabs.el));
  root.appendChild(body);

  // ── sync ──────────────────────────────────────────────────────────────────
  let crestKey = '';
  let peaceStateKey = '';
  let docsKey = '';

  function render(state: GameState): void {
    const id = view.get().openParleyId;
    if (id !== parleyId) {
      parleyId = id;
      chatKey = '';
      crestKey = '';
      peaceStateKey = '';
      docsKey = '';
    }

    const parley = id ? state.parleys[id] : undefined;
    const myGuildId = state.players[state.meId]?.guildId;
    if (!parley || !myGuildId) {
      if (crestKey !== 'none') {
        crestKey = 'none';
        clear(crest);
        crest.appendChild(el('span', { text: 'NO CHANNEL SELECTED' }));
        clear(statusSlot);
      }
      return;
    }

    channel = parleyChannel(parley.id);
    const themId = otherGuild(parley, myGuildId);
    const mine = state.guilds[myGuildId];
    const them = state.guilds[themId];

    const nextCrest = `${mine?.id ?? ''}:${mine?.color ?? 0}:${them?.id ?? ''}:${them?.color ?? 0}`;
    if (nextCrest !== crestKey) {
      crestKey = nextCrest;
      clear(crest);
      if (mine) crest.appendChild(guildSigil(mine, 26));
      crest.appendChild(
        el('span', {
          style: mine ? `color:${cssHex(mine.color)}` : undefined,
          text: mine?.tag ?? '???',
        }),
      );
      crest.appendChild(el('span', { text: '⇄' }));
      if (them) crest.appendChild(guildSigil(them, 26));
      crest.appendChild(
        el('span', {
          style: them ? `color:${cssHex(them.color)}` : undefined,
          text: them?.tag ?? '???',
        }),
      );
    }

    // ── peace state ──
    const nextPeace = `${parley.peace}:${parley.peaceSince ?? 0}`;
    if (nextPeace !== peaceStateKey) {
      peaceStateKey = nextPeace;
      peaceFlag.classList.toggle('is-peace', parley.peace);
      peaceKey.textContent = parley.peace ? 'AT PEACE' : 'NO PEACE DECLARED';
      peaceSince.textContent = parley.peace
        ? `DECLARED ${parley.peaceSince !== undefined ? stamp(parley.peaceSince) : '—'}`
        : 'the map is open between these banners';

      clear(statusSlot);
      statusSlot.appendChild(parley.peace ? badge('PEACE', 'ok') : badge('OPEN WAR', 'bad'));

      clear(peaceAction);
      peaceAction.appendChild(
        holdButton(parley.peace ? 'END PEACE' : 'DECLARE PEACE', {
          variant: parley.peace ? 'danger' : 'primary',
          holdMs: 1100,
          hint: parley.peace ? 'hold — both guilds are told' : 'hold — both guilds are told',
          onComplete: () => {
            const live = view.get().openParleyId;
            if (!live) return;
            void runAction(
              parley.peace ? 'PEACE ENDED' : 'PEACE DECLARED',
              backend.setPeace(live, !parley.peace),
            );
          },
        }),
      );
    }

    // ── thread ──
    const log = messages(state, channel);
    const nextChat = `${channel}:${log.length}:${log[log.length - 1]?.id ?? ''}`;
    if (nextChat !== chatKey) {
      chatKey = nextChat;
      chatView.setMessages(log, state.meId);
    }

    // ── trade ──
    tradePanelView.sync(state, parley.id);

    // ── documents ──
    const treaties = treatiesFor(state, parley.id);
    const nextDocs = treaties
      .map((t) => `${t.id}:${t.status}:${t.signatures.length}:${t.revisions.length}:${t.editingGuild}`)
      .join('|');
    if (nextDocs !== docsKey) {
      docsKey = nextDocs;
      clear(docList);
      if (treaties.length === 0) {
        docList.appendChild(emptyState('◇', 'no documents opened on this channel'));
      } else {
        for (const treaty of treaties) {
          const signed = treaty.status === 'signed';
          const holder = state.guilds[treaty.editingGuild];
          const row = el('button', { class: 'arch__item', attrs: { type: 'button' } });
          row.appendChild(
            el(
              'div',
              { class: 'grow' },
              el('div', { class: 'arch__title', text: treaty.title }),
              el('div', {
                class: 'arch__meta',
                text: signed
                  ? `EXECUTED ${treaty.signedAt !== undefined ? stamp(treaty.signedAt) : '—'} · ${treaty.signatures.length}/2 SIGNATURES`
                  : `PEN: ${holder?.tag ?? '???'} · REV ${treaty.revisions.length} · ${fmtAgo(
                      treaty.createdAt,
                      state.now,
                    ).toUpperCase()}`,
              }),
            ),
          );
          row.appendChild(signed ? badge('SEALED', 'gold') : badge('DRAFTING', 'violet'));
          row.addEventListener('click', () => view.patch({ openTreatyId: treaty.id }));
          docList.appendChild(row);
        }
      }
    }
  }

  return {
    el: root,
    sync(state: GameState): void {
      render(state);
    },
    dispose(): void {
      tradePanelView.dispose();
      parleyId = undefined;
      channel = '';
      chatKey = '';
      crestKey = '';
      peaceStateKey = '';
      docsKey = '';
      clear(docList);
    },
  };
}
