/**
 * GDD §10 — structured cross-guild trade.
 *
 * "X minerals + Y gas ⇄ Z minerals + W gas; both sides confirm; delivery uses
 * the transfer-time rules."
 *
 * The builder never hides the logistics: an offer is not a teleport. Accepting
 * mints two real shipments between the two signing diplomats under the §9.3
 * distance timing, so the panel prints the resulting flight time before either
 * side commits — exactly for the proposal it can resolve, estimated across the
 * counterpart's diplomats for the proposal it cannot (the signing diplomat is
 * whoever answers).
 */
import type { IBackend } from '../../backend/IBackend';
import { otherGuild, tradesFor } from '../../game/diplomacy/diplomacy';
import { nearestOwnedHex, transferTime } from '../../game/guild/transfers';
import type { Cost, GameState, GuildId, ParleyId, PlayerId, TradeOffer } from '../../game/types';
import { badge, button, emptyState, ICONS, panel } from '../components';
import { clear, el, fmtDuration, fmtNum, haptic, svg as svgEl } from '../dom';
import { runAction } from '../guild/rosterTab';

const SWAP_ICON = `<svg viewBox="0 0 24 24"><path d="M4 8.5h13l-3.5-3.5M20 15.5H7l3.5 3.5"/></svg>`;

const STEPS = [0, 25, 50, 100, 250, 500, 1000];

/** Diplomats of a guild — the leader always counts (GDD §8). */
function diplomatsOf(state: GameState, guildId: GuildId): PlayerId[] {
  const guild = state.guilds[guildId];
  if (!guild) return [];
  const set = new Set<PlayerId>(guild.diplomats);
  set.add(guild.leaderId);
  return [...set].filter((id) => guild.memberIds.includes(id));
}

/** Flight-time window between one commander and every diplomat of a guild. */
function etaWindow(
  state: GameState,
  fromId: PlayerId,
  toGuildId: GuildId,
): { min: number; max: number } | undefined {
  let min = Infinity;
  let max = 0;
  for (const id of diplomatsOf(state, toGuildId)) {
    const toHex = nearestOwnedHex(state, id);
    if (toHex === undefined) continue;
    const fromHex = nearestOwnedHex(state, fromId, toHex);
    if (fromHex === undefined) continue;
    const { ms } = transferTime(state, fromHex, toHex);
    min = Math.min(min, ms);
    max = Math.max(max, ms);
  }
  if (!Number.isFinite(min)) return undefined;
  return { min, max };
}

function exactEta(state: GameState, a: PlayerId, b: PlayerId): number | undefined {
  const toHex = nearestOwnedHex(state, b);
  if (toHex === undefined) return undefined;
  const fromHex = nearestOwnedHex(state, a, toHex);
  if (fromHex === undefined) return undefined;
  return transferTime(state, fromHex, toHex).ms;
}

function costLine(cost: Cost): string {
  const parts: string[] = [];
  if (cost.m > 0) parts.push(`${fmtNum(cost.m)} M`);
  if (cost.g > 0) parts.push(`${fmtNum(cost.g)} G`);
  return parts.length > 0 ? parts.join(' + ') : 'NOTHING';
}

export interface TradePanelView {
  readonly el: HTMLElement;
  sync(state: GameState, parleyId: ParleyId | undefined): void;
  dispose(): void;
}

export function createTradePanel(backend: IBackend): TradePanelView {
  const root = el('div', { class: 'col' });

  const offer: Cost = { m: 0, g: 0 };
  const request: Cost = { m: 0, g: 0 };

  let parleyId: ParleyId | undefined;
  let lastState: GameState | null = null;

  function legField(
    label: string,
    read: () => number,
    write: (v: number) => void,
    ceiling: () => number | undefined,
  ): { el: HTMLElement; sync(): void } {
    const value = el('span', { class: 'tfleg__v', text: '0' });
    const chips = el('div', { class: 'row wrap', style: 'gap:4px' });
    const buttons: HTMLButtonElement[] = [];

    for (const step of STEPS) {
      const btn = el('button', {
        class: 'rsort__btn',
        attrs: { type: 'button' },
        text: step === 0 ? 'CLR' : `+${step}`,
      });
      btn.addEventListener('click', () => {
        haptic(7);
        if (step === 0) write(0);
        else {
          const cap = ceiling();
          const next = read() + step;
          write(cap === undefined ? next : Math.min(cap, next));
        }
        paint();
        refresh();
      });
      buttons.push(btn);
      chips.appendChild(btn);
    }

    const paint = (): void => {
      value.textContent = fmtNum(read());
      const cap = ceiling();
      for (let i = 0; i < STEPS.length; i++) {
        const step = STEPS[i];
        buttons[i].disabled = step > 0 && cap !== undefined && read() >= cap;
      }
    };

    return {
      el: el(
        'div',
        { class: 'tfleg' },
        el('div', { class: 'tfleg__head' }, el('span', { class: 'tfleg__k', text: label }), value),
        chips,
      ),
      sync: paint,
    };
  }

  const myMinerals = (): number | undefined => {
    const state = lastState;
    return state ? Math.floor(state.players[state.meId]?.minerals ?? 0) : undefined;
  };
  const myGas = (): number | undefined => {
    const state = lastState;
    return state ? Math.floor(state.players[state.meId]?.gas ?? 0) : undefined;
  };

  const giveM = legField('MINERALS', () => offer.m, (v) => {
    offer.m = v;
  }, myMinerals);
  const giveG = legField('GAS', () => offer.g, (v) => {
    offer.g = v;
  }, myGas);
  const wantM = legField('MINERALS', () => request.m, (v) => {
    request.m = v;
  }, () => undefined);
  const wantG = legField('GAS', () => request.g, (v) => {
    request.g = v;
  }, () => undefined);

  const arrow = el('div', { class: 'tradearrow' });
  arrow.appendChild(svgEl(SWAP_ICON));

  const builder = el(
    'div',
    { class: 'tradebuild' },
    el(
      'div',
      { class: 'tradeside tradeside--give' },
      el('span', { class: 'tradeside__k', text: 'WE GIVE' }),
      giveM.el,
      giveG.el,
    ),
    arrow,
    el(
      'div',
      { class: 'tradeside tradeside--want' },
      el('span', { class: 'tradeside__k', text: 'WE WANT' }),
      wantM.el,
      wantG.el,
    ),
  );

  const verdict = el('div', { class: 'tfverdict', text: 'BUILD AN OFFER' });
  const logistics = el('div', {
    class: 'mono dim-2',
    style: 'font-size:9px;line-height:1.65;letter-spacing:.04em;text-transform:uppercase',
    text: 'Accepting mints two real convoys under the §9.3 transfer rules — 3 min per hex, 5 min floor. Nothing teleports, and either side may withdraw until the other confirms.',
  });

  const proposeBtn = button('PUT IT ON THE TABLE', {
    variant: 'primary',
    wide: true,
    icon: ICONS.send,
    disabled: true,
    onClick: () => {
      const id = parleyId;
      if (!id) return;
      void (async () => {
        const done = await runAction(
          'OFFER TABLED',
          backend.proposeTrade(id, { m: offer.m, g: offer.g }, { m: request.m, g: request.g }),
        );
        if (done === undefined) return;
        offer.m = 0;
        offer.g = 0;
        request.m = 0;
        request.g = 0;
        giveM.sync();
        giveG.sync();
        wantM.sync();
        wantG.sync();
        refresh();
      })();
    },
  });

  const builderPanel = panel(
    { title: 'STRUCTURED OFFER', subtitle: 'both sides confirm before anything moves', accent: 'var(--amber)' },
    builder,
    verdict,
    logistics,
    proposeBtn,
  );

  const offerList = el('div', { class: 'col' });
  const offersPanel = panel(
    { title: 'ON THE TABLE', subtitle: 'open offers in this parley', accent: 'var(--cyan)' },
    offerList,
  );

  root.appendChild(builderPanel);
  root.appendChild(offersPanel);

  function refresh(): void {
    const state = lastState;
    if (!state || !parleyId) {
      verdict.className = 'tfverdict';
      verdict.textContent = 'NO CHANNEL OPEN';
      proposeBtn.disabled = true;
      return;
    }
    const parley = state.parleys[parleyId];
    const myGuildId = state.players[state.meId]?.guildId;
    if (!parley || !myGuildId) {
      proposeBtn.disabled = true;
      return;
    }

    if (offer.m + offer.g <= 0 && request.m + request.g <= 0) {
      verdict.className = 'tfverdict';
      verdict.textContent = 'BUILD AN OFFER';
      proposeBtn.disabled = true;
      return;
    }

    const me = state.players[state.meId];
    if (me && (me.minerals < offer.m || me.gas < offer.g)) {
      verdict.className = 'tfverdict is-bad';
      verdict.textContent = 'YOU DO NOT HOLD WHAT YOU ARE OFFERING';
      proposeBtn.disabled = true;
      return;
    }

    const range = etaWindow(state, state.meId, otherGuild(parley, myGuildId));
    verdict.className = 'tfverdict is-ok';
    verdict.textContent =
      range === undefined
        ? 'READY — DELIVERY TIME RESOLVES WHEN THEY ANSWER'
        : range.min === range.max
          ? `READY — ETA ${fmtDuration(range.min)} ON ACCEPTANCE`
          : `READY — ETA ${fmtDuration(range.min)}–${fmtDuration(range.max)} DEPENDING ON WHO SIGNS`;
    proposeBtn.disabled = false;
  }

  function renderOffers(state: GameState): void {
    clear(offerList);
    if (!parleyId) {
      offerList.appendChild(emptyState('◇', 'no channel open'));
      return;
    }
    const myGuildId = state.players[state.meId]?.guildId;
    const trades = tradesFor(state, parleyId);
    if (trades.length === 0) {
      offerList.appendChild(emptyState('◇', 'nothing on the table'));
      return;
    }

    for (const trade of trades) {
      offerList.appendChild(offerCard(state, trade, myGuildId));
    }
  }

  function offerCard(state: GameState, trade: TradeOffer, myGuildId: GuildId | undefined): HTMLElement {
    const mine = trade.fromGuild === myGuildId;
    const open = trade.status === 'open';
    const classes = ['offer', mine ? 'offer--mine' : 'offer--theirs'];
    if (!open) classes.push('offer--closed');
    const card = el('div', { class: classes.join(' ') });

    const head = el('div', { class: 'row' });
    head.appendChild(
      el('span', {
        class: 'grow truncate mono',
        style: 'font-size:10px;letter-spacing:.05em;text-transform:uppercase',
        text: `${trade.byName} · ${state.guilds[trade.fromGuild]?.tag ?? '???'}`,
      }),
    );
    head.appendChild(
      trade.status === 'open'
        ? badge('OPEN', 'gold')
        : trade.status === 'accepted'
          ? badge('EXECUTED', 'ok')
          : badge(trade.status.toUpperCase(), 'bad'),
    );
    card.appendChild(head);

    const terms = el('div', { class: 'offer__terms' });
    terms.appendChild(el('span', { class: 'paychip paychip--m', text: costLine(trade.offer) }));
    const swap = el('span', { class: 'tradearrow', style: 'width:18px;height:18px' });
    swap.appendChild(svgEl(SWAP_ICON));
    terms.appendChild(swap);
    terms.appendChild(el('span', { class: 'paychip paychip--g', text: costLine(trade.request) }));
    card.appendChild(terms);

    const eta = mine
      ? undefined
      : exactEta(state, trade.byId, state.meId);
    card.appendChild(
      el('div', {
        class: 'mono dim-2',
        style: 'font-size:9px;letter-spacing:.04em;text-transform:uppercase',
        text:
          eta === undefined
            ? `${mine ? 'YOUR OFFER' : 'THEIR OFFER'} · DELIVERY UNDER THE TRANSFER RULES`
            : `IF YOU ACCEPT: CONVOYS LAND IN ${fmtDuration(eta)}`,
      }),
    );

    if (open) {
      const acts = el('div', { class: 'row wrap', style: 'gap:6px' });
      if (mine) {
        acts.appendChild(
          button('WITHDRAW', {
            variant: 'danger',
            small: true,
            onClick: () => {
              void runAction('OFFER WITHDRAWN', backend.respondTrade(trade.id, false));
            },
          }),
        );
      } else {
        acts.appendChild(
          button('ACCEPT', {
            variant: 'primary',
            small: true,
            icon: ICONS.check,
            onClick: () => {
              void runAction('OFFER ACCEPTED', backend.respondTrade(trade.id, true));
            },
          }),
        );
        acts.appendChild(
          button('DECLINE', {
            variant: 'quiet',
            small: true,
            onClick: () => {
              void runAction('OFFER DECLINED', backend.respondTrade(trade.id, false));
            },
          }),
        );
      }
      card.appendChild(acts);
    }
    return card;
  }

  let offersKey = '';

  return {
    el: root,
    sync(state: GameState, id: ParleyId | undefined): void {
      lastState = state;
      if (id !== parleyId) {
        parleyId = id;
        offersKey = '';
      }

      giveM.sync();
      giveG.sync();
      wantM.sync();
      wantG.sync();
      refresh();

      const trades = id ? tradesFor(state, id) : [];
      const next = `${id ?? ''}:${trades.map((t) => `${t.id}${t.status}`).join(',')}`;
      if (next === offersKey) return;
      offersKey = next;
      renderOffers(state);
    },
    dispose(): void {
      lastState = null;
      parleyId = undefined;
      offersKey = '';
      clear(offerList);
    },
  };
}
