/**
 * GDD §10 / §12.5 — the Diplomacy screen.
 *
 * Parleys, structured trades, the treaty editor and the archive. Access to the
 * negotiating table is restricted to Leaders and designated Officers; everybody
 * else gets an explicit locked state — but the archive stays open to every
 * member of the guild, because that is what makes a signed treaty a public
 * record rather than a secret one.
 */
import '../../styles/guild.css';

import type { IBackend } from '../../backend/IBackend';
import { atPeaceWith, parleyBetween } from '../../game/diplomacy/diplomacy';
import { can, roleOf } from '../../game/guild/permissions';
import { guildPower } from '../../game/guild/power';
import { neighborIds } from '../../game/hex';
import { guildTileCounts } from '../../game/world/season';
import { game, setScreen, view } from '../../game/store';
import type { GameState, GuildId } from '../../game/types';
import {
  badge,
  button,
  emptyState,
  guildSigil,
  ICONS,
  panel,
  skeleton,
  tabs,
  TAB_ICONS,
  type TabsController,
} from '../components';
import { clear, cssHex, Disposer, el, fmtNum } from '../dom';
import type { Screen } from '../screen';
import { runAction } from '../guild/rosterTab';
import { createArchiveView } from '../diplomacy/archiveView';
import { createParleyView } from '../diplomacy/parleyView';
import { createTreatyEditor } from '../diplomacy/treatyEditor';

const LOCK_ICON = `<svg viewBox="0 0 24 24">
    <rect x="4.5" y="10.5" width="15" height="10" rx="2"/>
    <path d="M8 10.5V7.6a4 4 0 018 0v2.9"/>
    <path d="M12 14v3.2"/>
  </svg>`;

/**
 * Length of the shared frontier: adjacent hex pairs where one side is held by
 * `mine` and the other by a rival. One pass over the map, every rival counted.
 */
function frontiers(state: GameState, mine: GuildId): Record<GuildId, number> {
  const out: Record<GuildId, number> = {};
  const guildOfHex = (ownerId: string | undefined): GuildId | undefined =>
    ownerId ? state.players[ownerId]?.guildId : undefined;

  for (const hex of Object.values(state.world.hexes)) {
    if (guildOfHex(hex.ownerId) !== mine) continue;
    for (const id of neighborIds(hex.id)) {
      const neighbour = state.world.hexes[id];
      if (!neighbour) continue;
      const other = guildOfHex(neighbour.ownerId);
      if (other === undefined || other === mine) continue;
      out[other] = (out[other] ?? 0) + 1;
    }
  }
  return out;
}

export function createDiplomacyScreen(backend: IBackend): Screen {
  const root = el('div', { class: 'screen screen--flow dscreen' });

  const tabSlot = el('div', { style: 'flex:none' });
  const bodySlot = el('div', { class: 'gbody' });
  root.appendChild(tabSlot);
  root.appendChild(bodySlot);

  // ── directory ─────────────────────────────────────────────────────────────
  const dirList = el('div', { class: 'col' });
  const dirPane = el(
    'div',
    { class: 'gpane' },
    el(
      'div',
      { class: 'gscroll' },
      panel(
        { title: 'RIVAL BANNERS', subtitle: 'open a channel with any of them', accent: 'var(--violet)' },
        dirList,
      ),
    ),
  );

  const lockPane = el('div', { class: 'gpane' });
  const archiveView = createArchiveView(backend);
  const parleyView = createParleyView(backend);
  const treatyEditor = createTreatyEditor(backend);

  const body = el(
    'div',
    { class: 'gbody' },
    dirPane,
    archiveView.el,
    parleyView.el,
    treatyEditor.el,
    lockPane,
  );

  type Pane = 'directory' | 'archive' | 'parley' | 'treaty' | 'locked';
  const paneEls: Record<Pane, HTMLElement> = {
    directory: dirPane,
    archive: archiveView.el,
    parley: parleyView.el,
    treaty: treatyEditor.el,
    locked: lockPane,
  };

  let activePane: Pane = 'directory';
  function showPane(next: Pane): void {
    activePane = next;
    for (const key of Object.keys(paneEls) as Pane[]) {
      paneEls[key].classList.toggle('is-on', key === next);
    }
  }

  let tabId: 'directory' | 'archive' = 'directory';
  const tabBar: TabsController = tabs(
    [
      { id: 'directory', label: 'DIRECTORY', icon: TAB_ICONS.directory },
      { id: 'archive', label: 'ARCHIVE', icon: TAB_ICONS.archive },
    ],
    (id: string) => {
      if (id !== 'directory' && id !== 'archive') return;
      tabId = id;
      view.patch({ openParleyId: undefined, openTreatyId: undefined });
      const state = game.get();
      if (state) sync(state);
    },
    'directory',
  );

  // ── locked plate ──────────────────────────────────────────────────────────
  function renderLock(state: GameState, reason: 'no-guild' | 'no-clearance'): void {
    clear(lockPane);
    const glyph = el('div', { class: 'dlock__glyph' });
    glyph.insertAdjacentHTML('beforeend', LOCK_ICON);

    const role = roleOf(state, state.meId);
    const block = el(
      'div',
      { class: 'dlock' },
      glyph,
      el('div', {
        class: 'dlock__title',
        text: reason === 'no-guild' ? 'NO CHARTER' : 'CLEARANCE DENIED',
      }),
      el('div', {
        class: 'dlock__body',
        text:
          reason === 'no-guild'
            ? 'Diplomacy is conducted between guilds. File a charter or enlist with one, then the table opens.'
            : `The negotiating table is restricted to the Leader and to Officers the Leader has designated as diplomats. Your rank is ${
                role ? role.toUpperCase() : 'UNAFFILIATED'
              }. Ask the Leader for a seat — the Diplomacy Archive stays open to you either way.`,
      }),
      reason === 'no-guild'
        ? button('OPEN THE GUILD PANEL', {
            variant: 'primary',
            icon: ICONS.chevronRight,
            onClick: () => setScreen('guild'),
          })
        : button('READ THE ARCHIVE', {
            variant: 'ghost',
            icon: ICONS.chevronRight,
            onClick: () => {
              tabId = 'archive';
              tabBar.select('archive');
              const live = game.get();
              if (live) sync(live);
            },
          }),
    );
    lockPane.appendChild(el('div', { class: 'gscroll' }, block));
  }

  // ── directory render ──────────────────────────────────────────────────────
  let dirKey = '';

  function renderDirectory(state: GameState, myGuildId: GuildId): void {
    const tiles = guildTileCounts(state);
    const rivals = Object.values(state.guilds).filter((g) => g.id !== myGuildId);
    rivals.sort((a, b) => (tiles[b.id] ?? 0) - (tiles[a.id] ?? 0) || a.name.localeCompare(b.name));

    const next = rivals
      .map(
        (g) =>
          `${g.id}:${tiles[g.id] ?? 0}:${atPeaceWith(state, myGuildId, g.id)}:${
            parleyBetween(state, myGuildId, g.id)?.id ?? ''
          }`,
      )
      .join('|');
    if (next === dirKey) return;
    dirKey = next;

    const border = frontiers(state, myGuildId);

    clear(dirList);
    if (rivals.length === 0) {
      dirList.appendChild(emptyState('◇', 'no rival banners on the register'));
      return;
    }

    for (const guild of rivals) {
      const peace = atPeaceWith(state, myGuildId, guild.id);
      const existing = parleyBetween(state, myGuildId, guild.id);
      const power = guildPower(state, guild.id);
      const shared = border[guild.id] ?? 0;

      const row = el('div', {
        class: `dir ${peace ? 'dir--peace' : 'dir--war'}`,
        style: `--band:${cssHex(guild.color)}`,
      });

      const sig = el('div', { class: 'dir__sig' });
      sig.appendChild(guildSigil(guild, 32));
      row.appendChild(sig);

      const id = el('div', { class: 'dir__id' });
      const nameRow = el('div', { class: 'dir__name' });
      nameRow.appendChild(el('span', { text: guild.name }));
      nameRow.appendChild(
        el('span', {
          class: 'ghead__tag',
          style: `color:${cssHex(guild.color)};border-color:${cssHex(guild.color)}`,
          text: guild.tag,
        }),
      );
      nameRow.appendChild(peace ? badge('PEACE', 'ok') : badge('NO PACT', 'bad'));
      id.appendChild(nameRow);

      const stats = el('div', { class: 'dir__stats' });
      stats.appendChild(el('span', {}, 'TILES ', el('b', { text: String(tiles[guild.id] ?? 0) })));
      stats.appendChild(el('span', {}, 'POWER ', el('b', { text: fmtNum(power.total) })));
      stats.appendChild(el('span', {}, 'CMDR ', el('b', { text: String(guild.memberIds.length) })));
      stats.appendChild(
        el('span', { class: 'dir__border' }, 'BORDER ', el('b', { text: `${shared} EDGE${shared === 1 ? '' : 'S'}` })),
      );
      id.appendChild(stats);
      row.appendChild(id);

      row.appendChild(
        button(existing ? 'RESUME PARLEY' : 'OPEN PARLEY', {
          variant: existing ? 'ghost' : 'primary',
          small: true,
          onClick: () => {
            void (async () => {
              const parleyId = await runAction('CHANNEL OPEN', backend.openParley(guild.id));
              if (parleyId !== undefined) {
                view.patch({ openParleyId: parleyId, openTreatyId: undefined });
              }
            })();
          },
        }),
      );

      dirList.appendChild(row);
    }
  }

  // ── sync ──────────────────────────────────────────────────────────────────
  let chromeMode = '';

  function sync(state: GameState | null): void {
    if (!state) {
      if (chromeMode !== 'boot') {
        chromeMode = 'boot';
        clear(tabSlot);
        clear(bodySlot);
        bodySlot.appendChild(skeleton('block', 3));
      }
      return;
    }

    if (chromeMode !== 'live') {
      chromeMode = 'live';
      clear(bodySlot);
      clear(tabSlot);
      tabSlot.appendChild(tabBar.el);
      bodySlot.appendChild(body);
    }

    const me = state.players[state.meId];
    const myGuildId = me?.guildId;

    if (!myGuildId) {
      renderLock(state, 'no-guild');
      showPane('locked');
      tabBar.el.classList.add('hidden');
      return;
    }
    tabBar.el.classList.remove('hidden');

    const isDiplomat = can(state, state.meId, 'diplomacy');
    const v = view.get();

    if (tabId === 'archive') {
      archiveView.sync(state);
      showPane('archive');
      return;
    }

    if (!isDiplomat) {
      if (activePane !== 'locked') renderLock(state, 'no-clearance');
      showPane('locked');
      return;
    }

    if (v.openTreatyId && state.treaties[v.openTreatyId]) {
      treatyEditor.sync(state);
      showPane('treaty');
      return;
    }
    if (v.openTreatyId) view.patch({ openTreatyId: undefined });

    if (v.openParleyId && state.parleys[v.openParleyId]) {
      parleyView.sync(state);
      showPane('parley');
      return;
    }
    if (v.openParleyId) view.patch({ openParleyId: undefined });

    renderDirectory(state, myGuildId);
    showPane('directory');
  }

  const disposer = new Disposer();

  return {
    el: root,

    mount(): void {
      disposer.add(game.subscribe((state) => sync(state)));
      disposer.add(
        view.select(
          (v) => `${v.openParleyId ?? ''}|${v.openTreatyId ?? ''}`,
          () => sync(game.get()),
        ),
      );
      sync(game.get());
    },

    unmount(): void {
      disposer.dispose();
      dirKey = '';
    },
  };
}
