/**
 * GDD §10 — the blank-document treaty editor.
 *
 * Turn-based editing: one side writes, submits, and the pen passes. Either side
 * may sign whatever is currently on the table; a new revision voids any prior
 * signature because a signature attests to an exact text. When both guilds have
 * signed, the document freezes and is presented as a formal instrument.
 *
 * The screen states plainly and permanently that a treaty binds nothing
 * mechanically (GDD §10, §14). There is no enforcement here and there never
 * will be — that is the design, not a shortcut.
 */
import type { IBackend } from '../../backend/IBackend';
import { holdsThePen } from '../../game/diplomacy/diplomacy';
import { can } from '../../game/guild/permissions';
import { view } from '../../game/store';
import type { GameState, Treaty, TreatyId } from '../../game/types';
import {
  badge,
  button,
  emptyState,
  holdButton,
  ICONS,
  panel,
  sectionHeader,
} from '../components';
import { clear, el, fmtAgo, haptic } from '../dom';
import { runAction } from '../guild/rosterTab';
import { stamp, treatyDocument } from './archiveView';

export interface TreatyEditorView {
  readonly el: HTMLElement;
  sync(state: GameState): void;
  dispose(): void;
}

const SOCIAL_NOTE =
  'This document restricts nothing. Signing it will not stop a single army, capture or battle on either side. It is a record — timestamped, counter-signed and archived in both guilds — so that keeping the terms, or breaking them, is provable.';

export function createTreatyEditor(backend: IBackend): TreatyEditorView {
  const root = el('div', { class: 'gpane' });

  const backBtn = button('BACK', {
    variant: 'quiet',
    small: true,
    icon: ICONS.chevronLeft,
    onClick: () => view.patch({ openTreatyId: undefined }),
  });
  const titleNode = el('div', { class: 'obj__title grow', text: '—' });
  const statusSlot = el('div', { class: 'row', style: 'gap:4px;flex:none' });
  const head = el('div', { class: 'row', style: 'flex:none' }, backBtn, titleNode, statusSlot);

  const penNode = el('div', { class: 'pen' });
  const penDot = el('span', { class: 'pen__dot', aria: { hidden: 'true' } });
  const penText = el('span', { class: 'grow' });
  penNode.appendChild(penDot);
  penNode.appendChild(penText);

  const surface = el('textarea', {
    class: 'tty__surface selectable',
    attrs: {
      placeholder:
        'ARTICLE I —\n\nWrite the terms in plain language. Both sides may edit until both sides sign.',
      maxlength: 4000,
      spellcheck: 'false',
    },
  });

  const submitBtn = button('SUBMIT REVISION', {
    variant: 'primary',
    wide: true,
    icon: ICONS.send,
    sub: 'files your text and passes the pen',
    onClick: () => {
      const id = currentId;
      if (!id) return;
      void runAction('REVISION FILED', backend.submitTreatyRevision(id, surface.value));
    },
  });

  const signBtn = holdButton('SIGN THE DOCUMENT', {
    variant: 'primary',
    holdMs: 1400,
    hint: 'hold to affix your signature',
    onComplete: () => {
      const id = currentId;
      if (!id) return;
      void runAction('SIGNATURE AFFIXED', backend.signTreaty(id));
    },
  });

  const signHint = el('div', { class: 'tfverdict' });
  const sigState = el('div', { class: 'col' });
  const revList = el('div', { class: 'col' });
  const docSlot = el('div');

  const note = el(
    'div',
    { class: 'tty__note' },
    el('b', { text: 'SOCIALLY ENFORCED ONLY. ' }),
    SOCIAL_NOTE,
  );

  const editorPanel = panel(
    { title: 'DOCUMENT', subtitle: 'turn-based drafting', accent: 'var(--gold)' },
    penNode,
    surface,
    signHint,
    submitBtn,
    signBtn,
    note,
  );

  const signaturePanel = panel(
    { title: 'SIGNATURES', subtitle: 'one per guild', accent: 'var(--cyan)' },
    sigState,
  );

  const historyPanel = panel(
    { title: 'REVISION HISTORY', subtitle: 'who wrote what, and when', accent: 'var(--violet)' },
    revList,
  );

  const scroll = el(
    'div',
    { class: 'gscroll' },
    docSlot,
    editorPanel,
    signaturePanel,
    historyPanel,
  );
  root.appendChild(head);
  root.appendChild(scroll);

  let currentId: TreatyId | undefined;
  let textKey = '';
  let shellKey = '';
  let revKey = '';

  surface.addEventListener('input', () => refreshSignHint());

  let liveTreaty: Treaty | undefined;
  let livePen = false;

  function refreshSignHint(): void {
    if (!liveTreaty) return;
    if (liveTreaty.status === 'signed') {
      signHint.className = 'tfverdict is-ok';
      signHint.textContent = 'EXECUTED — THE TEXT IS FROZEN';
      return;
    }
    const dirty = livePen && surface.value !== liveTreaty.text;
    if (dirty) {
      signHint.className = 'tfverdict';
      signHint.textContent = 'UNFILED EDITS — SUBMIT THE REVISION BEFORE SIGNING';
      signBtn.classList.add('is-disabled');
      return;
    }
    if (surface.value.trim().length === 0) {
      signHint.className = 'tfverdict';
      signHint.textContent = 'NOTHING WRITTEN TO SIGN';
      signBtn.classList.add('is-disabled');
      return;
    }
    signHint.className = 'tfverdict is-ok';
    signHint.textContent = 'READY TO SIGN';
    signBtn.classList.remove('is-disabled');
  }

  function renderSignatures(state: GameState, treaty: Treaty): void {
    clear(sigState);
    for (const guildId of treaty.guilds) {
      const guild = state.guilds[guildId];
      const signature = treaty.signatures.find((s) => s.guildId === guildId);
      const row = el('div', { class: 'rarmy' });
      row.appendChild(
        el('span', { class: 'rarmy__name', text: guild ? `${guild.name} [${guild.tag}]` : guildId }),
      );
      if (signature) {
        row.appendChild(el('span', { class: 'mono ok-t', style: 'font-size:9px', text: signature.playerName }));
        row.appendChild(
          el('span', { class: 'mono dim-2', style: 'font-size:9px', text: stamp(signature.at) }),
        );
      } else {
        row.appendChild(badge('UNSIGNED', 'bad'));
      }
      sigState.appendChild(row);
    }
  }

  function renderRevisions(state: GameState, treaty: Treaty): void {
    clear(revList);
    if (treaty.revisions.length === 0) {
      revList.appendChild(emptyState('◇', 'the page has never been written on'));
      return;
    }
    treaty.revisions.forEach((revision, index) => {
      const guild = state.guilds[revision.byGuild];
      const node = el('div', { class: 'rev' });
      node.appendChild(
        el(
          'div',
          { class: 'rev__head' },
          el('span', { class: 'rev__n', text: `REV ${index + 1}` }),
          el('span', { class: 'grow truncate', text: `${revision.byName} · ${guild?.tag ?? '???'}` }),
          el('span', { text: `${stamp(revision.at)} — ${fmtAgo(revision.at, state.now)}` }),
        ),
      );
      node.appendChild(
        el('div', {
          class: 'rev__text selectable',
          text: revision.text.trim().length > 0 ? revision.text : '— blanked —',
        }),
      );
      node.addEventListener('click', () => {
        node.classList.toggle('is-open');
        haptic(7);
      });
      revList.appendChild(node);
    });
  }

  function render(state: GameState): void {
    const id = view.get().openTreatyId;
    currentId = id;
    const treaty = id ? state.treaties[id] : undefined;
    liveTreaty = treaty;

    if (!treaty) {
      if (shellKey !== 'none') {
        shellKey = 'none';
        titleNode.textContent = 'NO DOCUMENT';
        clear(statusSlot);
        clear(docSlot);
        editorPanel.classList.add('hidden');
        signaturePanel.classList.add('hidden');
        historyPanel.classList.add('hidden');
      }
      return;
    }

    const meId = state.meId;
    const myGuildId = state.players[meId]?.guildId;
    const pen = id !== undefined && holdsThePen(state, meId, id);
    livePen = pen;
    const isDiplomat = can(state, meId, 'diplomacy');
    const signed = treaty.status === 'signed';
    const mySignature = myGuildId
      ? treaty.signatures.some((s) => s.guildId === myGuildId)
      : false;

    const nextShell = [
      treaty.id,
      treaty.status,
      treaty.editingGuild,
      treaty.signatures.length,
      pen,
      isDiplomat,
      mySignature,
    ].join('|');

    if (nextShell !== shellKey) {
      shellKey = nextShell;
      titleNode.textContent = treaty.title;

      clear(statusSlot);
      statusSlot.appendChild(signed ? badge('EXECUTED', 'gold') : badge('DRAFTING', 'violet'));

      editorPanel.classList.toggle('hidden', signed);
      signaturePanel.classList.toggle('hidden', signed);
      historyPanel.classList.remove('hidden');

      clear(docSlot);
      if (signed) docSlot.appendChild(treatyDocument(state, treaty));

      const holderGuild = state.guilds[treaty.editingGuild];
      penNode.classList.toggle('is-theirs', !pen);
      penText.textContent = signed
        ? 'THE PEN IS SPENT — THIS DOCUMENT IS FROZEN'
        : pen
          ? 'YOU HOLD THE PEN — WRITE, THEN SUBMIT TO PASS IT'
          : `PEN HELD BY ${holderGuild?.tag ?? '???'} — YOU MAY READ, OR SIGN AS IT STANDS`;

      surface.readOnly = !pen || signed;
      submitBtn.disabled = !pen || signed;
      signBtn.classList.toggle('is-disabled', signed || mySignature || !isDiplomat);
      if (mySignature && !signed) {
        signHint.className = 'tfverdict is-ok';
        signHint.textContent = 'YOUR GUILD HAS SIGNED — AWAITING THE COUNTER-SIGNATURE';
      }
    }

    const nextText = `${treaty.id}:${treaty.revisions.length}:${treaty.status}`;
    if (nextText !== textKey) {
      textKey = nextText;
      surface.value = treaty.text;
    }

    const nextRev = `${treaty.id}:${treaty.revisions.length}:${treaty.signatures.length}:${treaty.status}`;
    if (nextRev !== revKey) {
      revKey = nextRev;
      renderSignatures(state, treaty);
      renderRevisions(state, treaty);
    }

    if (!mySignature || signed) refreshSignHint();
  }

  return {
    el: root,
    sync(state: GameState): void {
      render(state);
    },
    dispose(): void {
      currentId = undefined;
      liveTreaty = undefined;
      textKey = '';
      shellKey = '';
      revKey = '';
      clear(docSlot);
      clear(sigState);
      clear(revList);
    },
  };
}
